pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        address user = address(0x1234);
        vm.deal(user, 10 ether);
        vm.prank(user);
        c.Put{value: 1 ether}(0);

        uint256 balanceBefore = address(user).balance;
        vm.prank(user);
        c.Collect(0);
        bool didSend = address(user).balance != balanceBefore;
