        // User puts 1 ether with unlockTime = 0
        vm.prank(user);
        c.Put{value: 1 ether}(0);

        // Warp past unlockTime
        vm.warp(1 days);

        // Try to collect 1 ether
        vm.prank(user);
        (bool success, ) = address(c).call{gas: 100000}(abi.encodeWithSelector(c.Collect.selector, 1 ether));

        // The reference contract deducts balance to 0; the buggy one reverts on sub_uint256 because balance was not checked
        assertTrue(success);
    }
}

