        c.Put{value: 1 ether}(block.timestamp + 100);
        vm.warp(block.timestamp + 50); // not yet unlockTime
        vm.prank(user);
        c.Collect(0.5 ether);
        // In reference: condition fails (block.timestamp <= unlockTime), so Collect does nothing
        // In buggy: call value 0.5 ether to user succeeds, deducts 0.5 from balance
