// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        address user = address(0x1234);
        vm.deal(user, 2 ether);

        // User puts 1 ether with unlockTime = 0
        vm.prank(user);
        c.Put{value: 1 ether}(0);

        // Warp past unlockTime (which is block.timestamp at Put time)
        vm.warp(block.timestamp + 1);

        // First collect of 1 ether - should succeed in both
        vm.prank(user);
        c.Collect(1 ether);

        // Second collect of 0.5 ether - should revert in reference because balance < MinSum
        vm.prank(user);
        bool ok;
        try c.Collect(0.5 ether) { ok = true; } catch { ok = false; }

        // In reference, after first collect, balance = 0, which is < MinSum (1 ether), so Collect reverts
        // In buggy version, condition removed, so external call always executes (sends 0.5 ether, likely fails but no revert)
        // Assert that reference reverts (ok == false) while buggy passes (ok == true)
        // We assert true meaning reference's behavior (revert) holds; buggy version breaks because ok would be true
        assertTrue(!ok);
    }
}

